'use client';

import { useDeferredValue, useMemo, useRef, useState } from 'react';
import katex from 'katex';
import 'katex/dist/katex.min.css';
import QueryLatex from '@/lib/algebra/latex';

// Renders a query in textbook notation (KaTeX). Output is generated by KaTeX from
// our own LaTeX, with `trust` off, so it is safe to inject.
export function MathBlock({ query, className }) {
  const html = useMemo(() => katex.renderToString(QueryLatex.toLatex(query), { throwOnError: false, displayMode: true, strict: 'ignore' }), [query]);
  return <div className={className} dangerouslySetInnerHTML={{ __html: html }} />;
}

export default function LatexPreview({ query }) {
  const deferred = useDeferredValue(query.trim());
  const latex = useMemo(() => QueryLatex.toLatex(deferred), [deferred]);
  const [copyLabel, setCopyLabel] = useState('Copiar LaTeX');
  const details = useRef(null);
  if (!deferred) return null;

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(latex);
      setCopyLabel('Copiado ✓');
    } catch {
      if (details.current) details.current.open = true;
      setCopyLabel('Selecione o código abaixo');
    }
    setTimeout(() => setCopyLabel('Copiar LaTeX'), 1800);
  };

  return (
    <div className="latex-preview">
      <div className="latex-head">
        <span className="symbol-toolbar-label">Notação formal</span>
        <button className="ghost-button latex-copy" type="button" onClick={copy}>{copyLabel}</button>
      </div>
      <MathBlock query={deferred} className="latex-render" />
      <details className="latex-source" ref={details}>
        <summary>Código LaTeX</summary>
        <pre>{latex}</pre>
      </details>
    </div>
  );
}
